cd /tmp/vtcheck && cat > pulse.mjs <<'EOF'
import { chromium } from 'playwright'
const browser = await chromium.launch()
for (const rm of ['no-preference', 'reduce']) {
  const ctx = await browser.newContext({ reducedMotion: rm })
  const page = await ctx.newPage()
  // Freeze on the skeleton by blocking the RSC data fetch for the detail page.
  await page.goto('http://localhost:3123/product/cotton-hoodie', { waitUntil: 'domcontentloaded' })
  const el = await page.$('.skeleton-text') || await page.$('.skeleton-image')
  const res = el
    ? await el.evaluate((n) => ({ anim: getComputedStyle(n).animationName, count: n.getAnimations().length }))
    : 'no skeleton visible (content already loaded)'
  console.log(`prefers-reduced-motion: ${rm.padEnd(13)} ->`, JSON.stringify(res))
  await ctx.close()
}
await browser.close()
EOF
timeout 120 node pulse.mjs 2>&1 | tail -10

cd /tmp/vtcheck && cat > backbtn.mjs <<'EOF'
import { chromium } from 'playwright'
const browser = await chromium.launch()
const ctx = await browser.newContext({ reducedMotion: 'no-preference', viewport: { width: 1000, height: 700 } })
const page = await ctx.newPage()
await page.goto('http://localhost:3124', { waitUntil: 'networkidle' })
await page.evaluate(() => {
  window.__vt = []
  const orig = document.startViewTransition.bind(document)
  document.startViewTransition = (arg) => {
    const t = orig(arg)
    const rec = { anims: [] }
    window.__vt.push(rec)
    t.ready.then(() => {
      rec.anims = document.getAnimations()
        .filter((a) => a.effect?.pseudoElement)
        .map((a) => `${a.effect.pseudoElement.replace('::view-transition-', '')} -> ${a.animationName}`)
    }).catch(() => {})
    return t
  }
})

await page.click('.product-card:nth-child(3)')
await page.waitForSelector('.product-hero')
await page.waitForTimeout(1200)
await page.evaluate(() => { window.__vt = [] })

await page.goBack()
await page.waitForSelector('.product-grid')
await page.waitForTimeout(1500)
const vt = await page.evaluate(() => window.__vt)
console.log('browser BACK button -> view transitions started:', vt.length)
vt.forEach((r, i) => console.log(` [${i + 1}]`, JSON.stringify(r.anims, null, 1)))
await browser.close()
EOF
timeout 150 node backbtn.mjs 2>&1 | tail -25
